window.PORTFOLIO_PROJECTS = {"order":["print-orchestrator","pfc-supervisor","ai-server","e3ng","voron-systems","metuned","motorsports","espresso-machine","uei-lab","abb-rexroth","makerspace-manufacturing"],"projects":{"print-orchestrator":{"id":"print-orchestrator","tone":"blue","eyebrow":"Printer fleet management","title":"Print Orchestrator","lede":"A single control surface for PrusaLink and Moonraker/Klipper printers. It separates printer, camera, power, job, and detection states so faults are easier to understand and recover from.","status":["Working system","3-printer fleet","Active development"],"image":"assets/screenshots/print-orchestrator-dashboard.png","imageAlt":"Print Orchestrator fleet dashboard","imageCaption":"Live fleet dashboard; real controls and private network details are removed from the demo.","imageFit":"contain","gallery":[{"src":"assets/screenshots/print-orchestrator-dashboard.png","alt":"Print Orchestrator fleet dashboard","title":"Fleet dashboard","copy":"The live interface keeps printer, camera, power, job, and detection states visible together.","kind":"screenshot","orientation":"portrait"},{"src":"assets/images/e3ng-img-7200-1.jpg","alt":"Networked probe and toolhead hardware on the E3NG printer","title":"Machine-level hardware","copy":"The dashboard represents real sensors, controllers, and machine-specific capabilities.","orientation":"portrait"},{"src":"assets/images/e3ng-img-7128-1.jpg","alt":"Controller and Raspberry Pi hardware used in the printer fleet","title":"Controller integration","copy":"The mixed fleet includes Linux hosts, printer controllers, and networked toolhead electronics.","orientation":"portrait"}],"metrics":[{"value":"3","label":"printers in the captured fleet"},{"value":"2","label":"printer API families"},{"value":"1","label":"shared operator view"},{"value":"Separated","label":"machine and service states"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>Why one dashboard was worth building.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Problem</p><h3>Too many separate interfaces</h3><p>The fleet mixes PrusaLink and Moonraker/Klipper. Checking jobs, cameras, temperatures, power, and fault states meant moving between several tools.</p></article><article><p class=\"project-eyebrow\">My work</p><h3>A practical operator view</h3><p>I designed the interface, integrated the services, packaged releases, and tested recovery paths against the printers I actually run.</p></article></div>"},{"id":"gallery","label":"Photos","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>The software and the machines behind it.</h2></div></div><div class=\"project-gallery gallery-count-3\"><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Fleet dashboard — The live interface keeps printer, camera, power, job, and detection states visible together.\"><img loading=\"lazy\" src=\"assets/screenshots/print-orchestrator-dashboard.png\" alt=\"Print Orchestrator fleet dashboard\"></button><figcaption><strong>Fleet dashboard</strong>The live interface keeps printer, camera, power, job, and detection states visible together.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Machine-level hardware — The dashboard represents real sensors, controllers, and machine-specific capabilities.\"><img loading=\"lazy\" src=\"assets/images/e3ng-img-7200-1.jpg\" alt=\"Networked probe and toolhead hardware on the E3NG printer\"></button><figcaption><strong>Machine-level hardware</strong>The dashboard represents real sensors, controllers, and machine-specific capabilities.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Controller integration — The mixed fleet includes Linux hosts, printer controllers, and networked toolhead electronics.\"><img loading=\"lazy\" src=\"assets/images/e3ng-img-7128-1.jpg\" alt=\"Controller and Raspberry Pi hardware used in the printer fleet\"></button><figcaption><strong>Controller integration</strong>The mixed fleet includes Linux hosts, printer controllers, and networked toolhead electronics.</figcaption></figure></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>Three choices keep the dashboard trustworthy.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Keep machine differences visible</h3><p>Shared concepts are normalized, but unsupported controls never appear as if they exist.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Separate partial failures</h3><p>Printer, camera, power, job, and detection states are reported independently.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Gate high-risk actions</h3><p>Power, emergency, console, and firmware controls use stronger warnings and machine context.</p></div></article></div>"},{"id":"workflow","label":"Workflow","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Workflow</p><h2>From machine telemetry to a safe operator action.</h2></div></div><div class=\"project-flow compact-flow\"><article><span>01</span><h3>Collect</h3><p>Read each printer and its supporting services.</p></article><article><span>02</span><h3>Normalize</h3><p>Map shared states without hiding machine-specific limits.</p></article><article><span>03</span><h3>Present</h3><p>Place evidence and available actions together.</p></article><article><span>04</span><h3>Verify</h3><p>Confirm the machine returned to a safe state after recovery.</p></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The fleet is easier to read and recover.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>One operating surface</h3><p>The whole fleet can be checked without opening several dashboards.</p></article><article><span>02</span><h3>Faster fault isolation</h3><p>The interface shows which subsystem actually failed.</p></article><article><span>03</span><h3>Room to extend</h3><p>The same structure can support routing, maintenance history, and richer detection.</p></article></div>"}],"next":"Continue improving part-detection feedback and make recovery history easier to compare.","fallbackPage":"projects/print-orchestrator/"},"pfc-supervisor":{"id":"pfc-supervisor","tone":"green","eyebrow":"Server power management","title":"PFC Supervisor","lede":"A control plane that lets the main AI server sleep during long idle windows while a low-power Pi keeps schedules, wake protection, and recovery logic available.","status":["Working system","Pi-retained control","Savings ledger"],"image":"assets/screenshots/pfc-power-management-top.png","imageAlt":"PFC power management command center","imageCaption":"Power-management view from the live PFC control plane.","imageFit":"contain","gallery":[{"src":"assets/screenshots/pfc-power-management-top.png","alt":"PFC power management command center","title":"Power command center","copy":"Workload state, suspend controls, and the current savings snapshot are shown in one place.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/pfc-energy-ledger.png","alt":"PFC energy ledger and savings charts","title":"Energy ledger","copy":"Observed sleep and estimated avoided energy remain separate so the savings claim is inspectable.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/pfc-ai-runtime.png","alt":"PFC AI runtime reconciliation panel","title":"Runtime recovery","copy":"Endpoints are checked again after wake, including model identity and required GPU offload.","kind":"screenshot","orientation":"portrait"},{"src":"assets/screenshots/pfc-eligibility-matrix.png","alt":"PFC subsystem eligibility matrix","title":"Suspend safety matrix","copy":"Each rule reports eligible, blocked, unknown, or stale instead of hiding the decision.","kind":"screenshot","orientation":"portrait"}],"metrics":[{"value":"95.0 h","label":"observed sleep in the snapshot"},{"value":"13.19 kWh","label":"estimated seven-day avoidance"},{"value":"68.23 kWh","label":"projected 30-day savings"},{"value":"$290.54","label":"projected annual value"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>Why the AI server does not need to stay awake all day.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Problem</p><h3>High idle power, real availability needs</h3><p>The B70/PFP host draws meaningful power, but scheduled jobs and local services still need a reliable way to wake it.</p></article><article><p class=\"project-eyebrow\">My work</p><h3>Power policy with visible safeguards</h3><p>I built workload interlocks, Hermes schedule caching, wake and sleep control, runtime reconciliation, and a ledger that keeps estimates labeled.</p></article></div>"},{"id":"savings","label":"Power savings","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Power savings</p><h2>The captured week includes 95 hours of sleep.</h2></div></div>\n<div class=\"project-savings-spotlight\">\n  <div class=\"project-savings-main\"><p class=\"project-eyebrow\">Seven-day snapshot</p><h3>13.19 kWh estimated avoided</h3><div class=\"project-savings-kpis-mini\"><article><strong>2.27 kWh</strong><span>average estimated daily savings</span></article><article><strong>68.23 kWh</strong><span>projected over 30 days</span></article><article><strong>$290.54</strong><span>projected annual value</span></article></div><div aria-label=\"Seven-day avoided energy chart\" class=\"project-savings-chart\"><article><i style=\"--height:90%\"></i><span>Fri</span></article><article><i style=\"--height:94%\"></i><span>Sat</span></article><article><i style=\"--height:87%\"></i><span>Sun</span></article><article><i style=\"--height:55%\"></i><span>Mon</span></article><article><i style=\"--height:63%\"></i><span>Tue</span></article><article><i style=\"--height:52%\"></i><span>Wed</span></article><article><i style=\"--height:18%\"></i><span>Thu</span></article></div></div>\n  <aside class=\"project-savings-note\"><p class=\"project-eyebrow\">Measurement note</p><strong>Sleep is observed; avoided energy is estimated.</strong><p>The ledger uses retained state history and configured power baselines. Direct host metering is the next accuracy upgrade, and the Pi's own consumption remains part of the combined estimate.</p></aside>\n</div>"},{"id":"gallery","label":"Screens","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>The control plane, energy ledger, and safety checks.</h2></div></div><div class=\"project-gallery gallery-count-4\"><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Power command center — Workload state, suspend controls, and the current savings snapshot are shown in one place.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-power-management-top.png\" alt=\"PFC power management command center\"></button><figcaption><strong>Power command center</strong>Workload state, suspend controls, and the current savings snapshot are shown in one place.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Energy ledger — Observed sleep and estimated avoided energy remain separate so the savings claim is inspectable.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-energy-ledger.png\" alt=\"PFC energy ledger and savings charts\"></button><figcaption><strong>Energy ledger</strong>Observed sleep and estimated avoided energy remain separate so the savings claim is inspectable.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Runtime recovery — Endpoints are checked again after wake, including model identity and required GPU offload.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-ai-runtime.png\" alt=\"PFC AI runtime reconciliation panel\"></button><figcaption><strong>Runtime recovery</strong>Endpoints are checked again after wake, including model identity and required GPU offload.</figcaption></figure><figure class=\"screenshot portrait\"><button type=\"button\" data-lightbox data-caption=\"Suspend safety matrix — Each rule reports eligible, blocked, unknown, or stale instead of hiding the decision.\"><img loading=\"lazy\" src=\"assets/screenshots/pfc-eligibility-matrix.png\" alt=\"PFC subsystem eligibility matrix\"></button><figcaption><strong>Suspend safety matrix</strong>Each rule reports eligible, blocked, unknown, or stale instead of hiding the decision.</figcaption></figure></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>The system is designed to fail safely.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Keep control on the Pi</h3><p>Schedules and wake logic remain available when the large host is asleep.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Block on uncertain state</h3><p>Unknown, stale, or active-workload conditions stop automatic suspend.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Reconcile after wake</h3><p>Endpoints, model identity, process state, and required GPU offload are checked again.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>PFC turns idle time into controlled sleep.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Lower estimated energy use</h3><p>The current ledger shows a meaningful reduction against the always-on baseline.</p></article><article><span>02</span><h3>Scheduled work stays protected</h3><p>Hermes cache windows remain visible on the Pi.</p></article><article><span>03</span><h3>Every sleep decision is explainable</h3><p>The safety matrix shows exactly what allowed or blocked suspend.</p></article></div>"}],"next":"Add direct host metering so savings can move from modeled attribution to measured wall power.","fallbackPage":"projects/pfc-supervisor/"},"ai-server":{"id":"ai-server","tone":"orange","eyebrow":"Local AI infrastructure","title":"B70 local AI server","lede":"A custom local-inference server used to benchmark models and run the services behind Print Orchestrator, PFC, and engineering workflows.","status":["Active platform","Local inference","Measured benchmarks"],"image":"assets/images/ai-img-8931.jpg","imageAlt":"Custom B70 local AI server installation","imageCaption":"Installed B70 server in its working environment.","imageFit":"contain","gallery":[{"src":"assets/images/ai-img-8931.jpg","alt":"Custom B70 local AI server installation","title":"Installed B70 system","copy":"The server is a working local-inference platform rather than a benchmark-only test bench.","orientation":"portrait"},{"src":"assets/images/ai-img-8916.jpg","alt":"Open B70 server chassis showing internal hardware","title":"Hardware integration","copy":"The build combines compute, cooling, power, and service access inside a custom enclosure.","orientation":"portrait"},{"src":"assets/images/ai-calculator-code-2.jpg","alt":"Local AI coding workflow and calculator tool test","title":"Applied local workflow","copy":"Models are tested on engineering tasks, tool use, and service integration—not only token speed.","orientation":"portrait"}],"metrics":[{"value":"93.31 tok/s","label":"Qwen3 30B MoE result"},{"value":"72.91 tok/s","label":"Qwen3.6 35B MoE result"},{"value":"20.61 GiB","label":"largest active benchmark shown"},{"value":"Private","label":"local inference and tooling"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A server built for practical local AI work.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Purpose</p><h3>Run useful models locally</h3><p>The platform supports private inference, software development, engineering tools, and the services that coordinate the rest of the lab.</p></article><article><p class=\"project-eyebrow\">My work</p><h3>Hardware through runtime</h3><p>I integrated the hardware, cooling, Linux services, llama.cpp launches, model testing, benchmarks, and recovery behavior.</p></article></div>"},{"id":"gallery","label":"Photos","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>The server, internal hardware, and an applied workflow.</h2></div></div><div class=\"project-gallery gallery-count-3\"><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Installed B70 system — The server is a working local-inference platform rather than a benchmark-only test bench.\"><img loading=\"lazy\" src=\"assets/images/ai-img-8931.jpg\" alt=\"Custom B70 local AI server installation\"></button><figcaption><strong>Installed B70 system</strong>The server is a working local-inference platform rather than a benchmark-only test bench.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Hardware integration — The build combines compute, cooling, power, and service access inside a custom enclosure.\"><img loading=\"lazy\" src=\"assets/images/ai-img-8916.jpg\" alt=\"Open B70 server chassis showing internal hardware\"></button><figcaption><strong>Hardware integration</strong>The build combines compute, cooling, power, and service access inside a custom enclosure.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Applied local workflow — Models are tested on engineering tasks, tool use, and service integration—not only token speed.\"><img loading=\"lazy\" src=\"assets/images/ai-calculator-code-2.jpg\" alt=\"Local AI coding workflow and calculator tool test\"></button><figcaption><strong>Applied local workflow</strong>Models are tested on engineering tasks, tool use, and service integration—not only token speed.</figcaption></figure></div>"},{"id":"benchmarks","label":"Benchmarks","html":"<div class=\"project-section-heading\"><div><p class=\"project-eyebrow\">Benchmarks</p><h2>Generation rates measured on the B70 system.</h2></div><p>Results depend on the model, quantization, context, and launch settings.</p></div><div class=\"project-special-table-wrap\"><table class=\"project-special-table\"><thead><tr><th>Model</th><th>Class</th><th>Size</th><th>Generation</th></tr></thead><tbody><tr class=\"\"><td><strong>qwen2.5-0.5b-instruct-q4_k_m</strong></td><td>Dense tiny</td><td>0.46 GiB</td><td>223.42 tok/s</td></tr><tr class=\"\"><td><strong>gemma-4-E2B-it-UD-Q4_K_XL</strong></td><td>Small Gemma</td><td>2.97 GiB</td><td>128.83 tok/s</td></tr><tr class=\"highlight\"><td><strong>Qwen3-30B-A3B-Instruct-2507-Q4_K_M</strong></td><td>MoE</td><td>17.28 GiB</td><td>93.31 tok/s</td></tr><tr class=\"\"><td><strong>gemma-4-E4B-it-UD-Q4_K_XL</strong></td><td>Small Gemma</td><td>4.77 GiB</td><td>87.54 tok/s</td></tr><tr class=\"\"><td><strong>gemma-4-26B-A4B-it-UD-Q4_K_M</strong></td><td>MoE</td><td>15.78 GiB</td><td>73.67 tok/s</td></tr><tr class=\"highlight\"><td><strong>Qwen3.6-35B-A3B-UD-Q4_K_M</strong></td><td>MoE</td><td>20.61 GiB</td><td>72.91 tok/s</td></tr><tr class=\"\"><td><strong>gemma-4-12b-it-UD-Q4_K_XL</strong></td><td>Dense</td><td>6.86 GiB</td><td>47.93 tok/s</td></tr><tr class=\"\"><td><strong>Mistral-Small-3.2-24B-Instruct-2506-Q4_K_M</strong></td><td>Dense</td><td>13.34 GiB</td><td>32.65 tok/s</td></tr><tr class=\"\"><td><strong>Qwen3.5-27B-Q4_K_M</strong></td><td>Dense</td><td>15.58 GiB</td><td>24.39 tok/s</td></tr><tr class=\"\"><td><strong>Qwen3-32B-Q4_K_M</strong></td><td>Dense</td><td>18.40 GiB</td><td>23.30 tok/s</td></tr><tr class=\"\"><td><strong>gemma-4-31B-it-UD-Q4_K_XL</strong></td><td>Dense</td><td>17.52 GiB</td><td>22.36–22.82 tok/s</td></tr><tr class=\"retired\"><td><strong>Qwen3.5-122B-A10B-UD-IQ3_S</strong></td><td>Retired stress test</td><td>retired</td><td>10.15–13.13 tok/s</td></tr></tbody></table></div><p class=\"project-special-note\"><strong>Historical stress test:</strong> the retired 122B model reached about 248 tok/s prompt processing at pp512 and 10.15–13.13 tok/s generation around <code>-ngl 35</code> with 16k–24k context. It was removed from the active stack because it was too large for practical daily use.</p>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>The model stack is chosen from measured behavior.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Benchmark on the real host</h3><p>Published model claims are not treated as a substitute for local measurements.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Optimize for useful throughput</h3><p>Model quality, memory use, prompt speed, generation speed, and stability all matter.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Test by role</h3><p>Manager and worker duties are evaluated separately instead of relying on one general score.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The server became a working engineering platform.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Repeatable model selection</h3><p>Benchmarks make tradeoffs visible before a model enters the active stack.</p></article><article><span>02</span><h3>Shared infrastructure</h3><p>PFC and Print Orchestrator now use the same host and service discipline.</p></article><article><span>03</span><h3>Practical local tools</h3><p>The system supports coding, analysis, orchestration, and private workflows.</p></article></div>"}],"next":"Continue role-specific model evaluations and improve runtime recovery after host sleep.","fallbackPage":"projects/ai-server/"},"e3ng":{"id":"e3ng","tone":"orange","eyebrow":"Custom motion platform","title":"E3NG CoreXY conversion","lede":"A heavily modified Ender 3 platform rebuilt as a CoreXY machine with Klipper, networked electronics, custom sensing, and a commissioning workflow based on measured calibration.","status":["Working machine","CoreXY + Klipper","Custom electronics"],"image":"assets/images/e3ng-img-7200-1.jpg","imageAlt":"Probe and toolhead hardware on the E3NG CoreXY printer","imageCaption":"Toolhead sensing and wiring on the working E3NG conversion.","imageFit":"contain","gallery":[{"src":"assets/images/e3ng-img-7200-1.jpg","alt":"Probe and toolhead hardware on the E3NG CoreXY printer","title":"Toolhead sensing","copy":"The custom toolhead combines probing, wiring, and motion-system packaging.","orientation":"portrait"},{"src":"assets/images/e3ng-img-7150-1.jpg","alt":"Klipper heightmap from E3NG bed mesh calibration","title":"Bed-mesh verification","copy":"Calibration data is used to verify geometry and compensate for the build surface.","orientation":"portrait"},{"src":"assets/images/e3ng-img-7128-1.jpg","alt":"E3NG controller and Raspberry Pi electronics","title":"Control hardware","copy":"The electronics stack ties the printer controller, Raspberry Pi, networking, and toolhead together.","orientation":"portrait"}],"metrics":[{"value":"CoreXY","label":"motion conversion"},{"value":"Klipper","label":"firmware and tuning"},{"value":"CAN-style","label":"networked toolhead work"},{"value":"Measured","label":"mesh and input-shaper tuning"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A printer rebuild that became a controls project.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Build</p><h3>Mechanical and electrical conversion</h3><p>The project combines CoreXY belt routing, extrusion geometry, toolhead packaging, controller integration, sensing, and power distribution.</p></article><article><p class=\"project-eyebrow\">My work</p><h3>Commissioning from first motion to repeatable parts</h3><p>I assembled the platform, configured Klipper, debugged the toolhead network, tuned motion, and verified bed geometry.</p></article></div>"},{"id":"gallery","label":"Photos","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>Sensing, calibration, and control hardware.</h2></div></div><div class=\"project-gallery gallery-count-3\"><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Toolhead sensing — The custom toolhead combines probing, wiring, and motion-system packaging.\"><img loading=\"lazy\" src=\"assets/images/e3ng-img-7200-1.jpg\" alt=\"Probe and toolhead hardware on the E3NG CoreXY printer\"></button><figcaption><strong>Toolhead sensing</strong>The custom toolhead combines probing, wiring, and motion-system packaging.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Bed-mesh verification — Calibration data is used to verify geometry and compensate for the build surface.\"><img loading=\"lazy\" src=\"assets/images/e3ng-img-7150-1.jpg\" alt=\"Klipper heightmap from E3NG bed mesh calibration\"></button><figcaption><strong>Bed-mesh verification</strong>Calibration data is used to verify geometry and compensate for the build surface.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Control hardware — The electronics stack ties the printer controller, Raspberry Pi, networking, and toolhead together.\"><img loading=\"lazy\" src=\"assets/images/e3ng-img-7128-1.jpg\" alt=\"E3NG controller and Raspberry Pi electronics\"></button><figcaption><strong>Control hardware</strong>The electronics stack ties the printer controller, Raspberry Pi, networking, and toolhead together.</figcaption></figure></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>The build was treated as a complete machine.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Tune after the mechanics are sound</h3><p>Firmware compensation does not replace square frames, correct belt paths, or reliable motion.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Use measurement for calibration</h3><p>Heightmaps and input-shaper data guide changes instead of visual guesses.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Make electronics serviceable</h3><p>Controller, Pi, toolhead, and sensor connections stay reachable for diagnosis.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The conversion produced a usable custom platform.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Working CoreXY motion</h3><p>The rebuilt kinematics and firmware operate as one system.</p></article><article><span>02</span><h3>Better troubleshooting habits</h3><p>Mechanical, electrical, and software faults are isolated in a repeatable order.</p></article><article><span>03</span><h3>Transferable controls experience</h3><p>The project mirrors small-scale commissioning and equipment support.</p></article></div>"}],"next":"Keep improving enclosure, thermal behavior, and repeatable technical-material profiles.","fallbackPage":"projects/e3ng/"},"voron-systems":{"id":"voron-systems","tone":"orange","eyebrow":"Printer commissioning","title":"Voron printer systems","lede":"An enclosed CoreXY platform used as a reliable workcell for technical materials, functional parts, calibration, and maintenance practice.","status":["Working system","Voron 2.4","Technical materials"],"image":"assets/images/voron-img-6388-1.jpg","imageAlt":"Voron printer toolhead and printed mechanical components","imageCaption":"Functional printed assembly produced on the Voron-class system.","imageFit":"contain","gallery":[{"src":"assets/images/voron-img-6388-1.jpg","alt":"Voron printer toolhead and printed mechanical components","title":"Functional printed assembly","copy":"The system is used to produce and validate real mechanical parts in technical materials.","orientation":"portrait"}],"metrics":[{"value":"Voron 2.4","label":"enclosed CoreXY platform"},{"value":"ASA","label":"technical-material capability"},{"value":"4-point","label":"gantry and Z alignment"},{"value":"Repeatable","label":"profiles and maintenance"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A printer treated as production equipment.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Purpose</p><h3>Reliable functional prototyping</h3><p>The enclosed machine supports larger parts and technical materials that need controlled motion, temperature, and repeatable setup.</p></article><article><p class=\"project-eyebrow\">My work</p><h3>Assembly, tuning, and maintenance</h3><p>I handled frame accuracy, belts, gantry alignment, electronics, toolheads, calibration, profiles, and fault isolation.</p></article></div>"},{"id":"gallery","label":"Photo","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>A functional part from the working system.</h2></div></div><div class=\"project-gallery gallery-count-1\"><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Functional printed assembly — The system is used to produce and validate real mechanical parts in technical materials.\"><img loading=\"lazy\" src=\"assets/images/voron-img-6388-1.jpg\" alt=\"Voron printer toolhead and printed mechanical components\"></button><figcaption><strong>Functional printed assembly</strong>The system is used to produce and validate real mechanical parts in technical materials.</figcaption></figure></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>Reliability comes from disciplined setup.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Build square before tuning</h3><p>Frame and gantry geometry establish the limit of later calibration.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Control the thermal environment</h3><p>Enclosure behavior and material profiles are part of the mechanical process.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Document maintenance</h3><p>Repeatable checks make ambiguous failures easier to isolate.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The machine supports repeatable technical work.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Functional parts</h3><p>The system produces components for other engineering builds.</p></article><article><span>02</span><h3>Commissioning experience</h3><p>Assembly, inspection, tuning, and verification are handled as one workflow.</p></article><article><span>03</span><h3>Uptime mindset</h3><p>Maintenance and recovery are treated as part of machine ownership.</p></article></div>"}],"next":"Add more documented examples of finished technical-material parts and their design requirements.","fallbackPage":"projects/voron-systems/"},"metuned":{"id":"metuned","tone":"orange","eyebrow":"Motorsports product development","title":"Metuned digital dash","lede":"A low-cost digital dashboard concept created from a real endurance-racing information gap. I led enclosure, packaging, cooling, prototype presentation, and product direction.","status":["Co-founder / CDO","Working prototype","Product development"],"image":"assets/images/metuned-copy-of-proto-2.jpg","imageAlt":"Metuned digital dashboard enclosure prototype","imageCaption":"Printed enclosure prototype for the Metuned digital dash.","imageFit":"cover","gallery":[{"src":"assets/images/metuned-copy-of-proto-2.jpg","alt":"Metuned digital dashboard enclosure prototype","title":"Enclosure prototype","copy":"The printed housing establishes display fit, airflow, service access, and product identity.","orientation":"landscape"},{"src":"assets/images/metuned-copy-of-proto-4-1.jpg","alt":"Metuned electronics prototype board","title":"Electronics fitment","copy":"PCB placement, wiring, and cooling were evaluated as part of the product package.","orientation":"landscape"}],"metrics":[{"value":"Prototype","label":"printed enclosure and PCB fit"},{"value":"Cooling","label":"airflow and fan packaging"},{"value":"Serviceable","label":"wiring and access considered"},{"value":"Race-led","label":"problem came from track use"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A product idea built from a trackside failure.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Problem</p><h3>The driver needed better information</h3><p>Factory instrumentation did not make the race car&#x27;s condition clear enough during endurance use.</p></article><article><p class=\"project-eyebrow\">My work</p><h3>Turn the need into a physical product</h3><p>I shaped the enclosure, PCB package, cooling, service access, branding, and prototype story as Chief Design Officer.</p></article></div>"},{"id":"gallery","label":"Photos","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>Prototype enclosure and electronics fitment.</h2></div></div><div class=\"project-gallery gallery-count-2\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Enclosure prototype — The printed housing establishes display fit, airflow, service access, and product identity.\"><img loading=\"lazy\" src=\"assets/images/metuned-copy-of-proto-2.jpg\" alt=\"Metuned digital dashboard enclosure prototype\"></button><figcaption><strong>Enclosure prototype</strong>The printed housing establishes display fit, airflow, service access, and product identity.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Electronics fitment — PCB placement, wiring, and cooling were evaluated as part of the product package.\"><img loading=\"lazy\" src=\"assets/images/metuned-copy-of-proto-4-1.jpg\" alt=\"Metuned electronics prototype board\"></button><figcaption><strong>Electronics fitment</strong>PCB placement, wiring, and cooling were evaluated as part of the product package.</figcaption></figure></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>Packaging had to work inside a race car.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Design around the electronics</h3><p>Display, PCB, connectors, wiring, and cooling set the enclosure geometry.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Keep service access practical</h3><p>A prototype is more useful when it can be opened, rewired, and repaired.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Make the product readable</h3><p>Branding and interface presentation support trust as well as appearance.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The concept moved beyond a sketch.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Physical prototype</h3><p>The enclosure and electronics fit were tested together.</p></article><article><span>02</span><h3>Clear product direction</h3><p>The project has a defined use case, audience, and development path.</p></article><article><span>03</span><h3>Startup experience</h3><p>Technical work was connected to presentation, funding, and customer value.</p></article></div>"}],"next":"Document the next electronics revision and show the dash operating in a vehicle.","fallbackPage":"projects/metuned/"},"motorsports":{"id":"motorsports","tone":"orange","eyebrow":"Leadership and fabrication","title":"Sierra College Motorsports","lede":"Student-led race preparation, fabrication, events, sponsorship, and trackside problem solving around the “Notta Miata” Mini Cooper program.","status":["Club president","Race preparation","Community funding"],"image":"assets/images/motorsports-thebigpicture-1.jpg","imageAlt":"Sierra College Cars and Coffee event","imageCaption":"Cars and Coffee event organized to build support for the motorsports program.","imageFit":"cover","gallery":[{"src":"assets/images/motorsports-thebigpicture-1.jpg","alt":"Sierra College Cars and Coffee event","title":"Community-funded program","copy":"Cars and Coffee events built visibility, recruited support, and helped fund the race program.","orientation":"landscape"},{"src":"assets/images/motorsports-img-5023-2.jpg","alt":"Fabricated motorsports bracket and component repair","title":"Practical fabrication","copy":"Repairs and brackets were developed around real packaging, schedule, and service constraints.","orientation":"portrait"}],"metrics":[{"value":"$500","label":"starting Mini Cooper"},{"value":"3 roles","label":"treasurer to vice president to president"},{"value":"Lemons","label":"endurance-racing program"},{"value":"Team-led","label":"funding, repair, and execution"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A race program built under tight constraints.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Technical work</p><h3>Repair and fabricate what the car needed</h3><p>The team handled engine work, brackets, mounts, field repairs, and race preparation with limited time and budget.</p></article><article><p class=\"project-eyebrow\">Leadership</p><h3>Build the team around the car</h3><p>I helped organize funding, recruitment, events, sponsorship, task ownership, and trackside execution.</p></article></div>"},{"id":"gallery","label":"Photos","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>Community building and practical fabrication.</h2></div></div><div class=\"project-gallery gallery-count-2\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Community-funded program — Cars and Coffee events built visibility, recruited support, and helped fund the race program.\"><img loading=\"lazy\" src=\"assets/images/motorsports-thebigpicture-1.jpg\" alt=\"Sierra College Cars and Coffee event\"></button><figcaption><strong>Community-funded program</strong>Cars and Coffee events built visibility, recruited support, and helped fund the race program.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Practical fabrication — Repairs and brackets were developed around real packaging, schedule, and service constraints.\"><img loading=\"lazy\" src=\"assets/images/motorsports-img-5023-2.jpg\" alt=\"Fabricated motorsports bracket and component repair\"></button><figcaption><strong>Practical fabrication</strong>Repairs and brackets were developed around real packaging, schedule, and service constraints.</figcaption></figure></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>The solution had to be safe and ready on time.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Prioritize the failure that stops the car</h3><p>Repairs were sequenced around safety, reliability, and race deadlines.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Design for field service</h3><p>Brackets and fixes needed access, inspectability, and fast replacement.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Match tasks to the team</h3><p>Clear ownership helped students with different experience levels contribute.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The program became more than one car.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Working race project</h3><p>The Mini became a platform for repair, fabrication, and team learning.</p></article><article><span>02</span><h3>Sustainable outreach</h3><p>Events and sponsors helped create funding and visibility.</p></article><article><span>03</span><h3>Leadership under pressure</h3><p>Real deadlines required decisions that worked outside the classroom.</p></article></div>"}],"next":"Add a concise build timeline that connects major failures, repairs, and race outcomes.","fallbackPage":"projects/motorsports/"},"espresso-machine":{"id":"espresso-machine","tone":"orange","eyebrow":"ME190 senior design","title":"Hybrid hand-actuated espresso machine","lede":"A compact senior-design machine targeting 9 bar, a 2 oz shot, and a 25–30 second extraction while combining a hand-actuated mechanism with heating, sensing, and controls.","status":["Senior design","SendCutSend sponsored","Active build"],"image":"assets/images/espresso-img-4665.jpg","imageAlt":"ME190 espresso machine team presenting the project","imageCaption":"ME190 team presenting the project and its design targets.","imageFit":"cover","gallery":[{"src":"assets/images/espresso-img-4665.jpg","alt":"ME190 espresso machine team presenting the project","title":"Senior design presentation","copy":"The team presented the system targets, architecture, and planned validation approach.","orientation":"landscape"},{"src":"assets/images/espresso-image-113.jpg","alt":"Mechanical lever and pressure mechanism prototype for the espresso machine","title":"Lever mechanism","copy":"The prototype converts hand input into a controlled extraction-pressure path.","orientation":"portrait"},{"src":"assets/images/espresso-group1-standing.jpg","alt":"ME190 espresso machine project team","title":"Project team","copy":"The project combines mechanical, electrical, controls, documentation, and sponsored fabrication work.","orientation":"landscape"}],"metrics":[{"value":"$750","label":"SendCutSend store credit plus merchandise"},{"value":"9 bar","label":"target extraction pressure"},{"value":"2 oz ±10%","label":"target shot volume"},{"value":"25–30 s","label":"target extraction time"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>A compact machine with mechanical and controls constraints.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">System</p><h3>Hand input with controlled extraction</h3><p>The design combines a lever mechanism, heating, pumping, sensors, and controls inside a compact package.</p></article><article><p class=\"project-eyebrow\">My work</p><h3>Electrical and system integration</h3><p>I contributed electrical fundamentals, efficiency constraints, wattage calculations, PID-control planning, documentation, and cross-system integration.</p></article></div>"},{"id":"gallery","label":"Photos","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>The team, presentation, and lever mechanism.</h2></div></div><div class=\"project-gallery gallery-count-3\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Senior design presentation — The team presented the system targets, architecture, and planned validation approach.\"><img loading=\"lazy\" src=\"assets/images/espresso-img-4665.jpg\" alt=\"ME190 espresso machine team presenting the project\"></button><figcaption><strong>Senior design presentation</strong>The team presented the system targets, architecture, and planned validation approach.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Lever mechanism — The prototype converts hand input into a controlled extraction-pressure path.\"><img loading=\"lazy\" src=\"assets/images/espresso-image-113.jpg\" alt=\"Mechanical lever and pressure mechanism prototype for the espresso machine\"></button><figcaption><strong>Lever mechanism</strong>The prototype converts hand input into a controlled extraction-pressure path.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Project team — The project combines mechanical, electrical, controls, documentation, and sponsored fabrication work.\"><img loading=\"lazy\" src=\"assets/images/espresso-group1-standing.jpg\" alt=\"ME190 espresso machine project team\"></button><figcaption><strong>Project team</strong>The project combines mechanical, electrical, controls, documentation, and sponsored fabrication work.</figcaption></figure></div>"},{"id":"sponsorship","label":"Sponsorship","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Sponsorship</p><h2>SendCutSend is supporting the next fabrication step.</h2></div></div><div class=\"project-milestone\"><div class=\"project-milestone-metric\"><div><strong>$750</strong><span>store credit plus merchandise</span></div></div><div class=\"project-milestone-copy\"><p class=\"project-eyebrow\">Recent milestone</p><h3>Outside support for production-intent parts</h3><p>The sponsorship gives the team more room to order accurate cut parts and document material, geometry, assembly, and test results.</p></div></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>The machine has to balance force, heat, water, and controls.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Design around measurable shot targets</h3><p>Pressure, volume, time, and temperature define whether the concept works.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Integrate the electrical load early</h3><p>Heaters, pump, sensors, and controls affect power, packaging, and safety.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Use sponsored parts as testable hardware</h3><p>Cut components should connect directly to assembly and validation evidence.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The project now has a clearer path into fabrication.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Defined performance targets</h3><p>The team can test the machine against pressure, time, volume, and temperature.</p></article><article><span>02</span><h3>External validation</h3><p>SendCutSend sponsorship supports the credibility of the build.</p></article><article><span>03</span><h3>Integrated documentation</h3><p>Drawings, calculations, BOMs, and test plans stay connected to the hardware.</p></article></div>"}],"next":"Show the sponsored parts, assembly progress, and first extraction-test data as they become available.","fallbackPage":"projects/espresso-machine/"},"uei-lab":{"id":"uei-lab","tone":"orange","eyebrow":"Test engineering","title":"UEI energy-efficiency testing","lede":"Standards-driven appliance testing support for residential fan airflow and portable-spa energy efficiency through University Enterprises and Sacramento State.","status":["Professional lab work","CFM instrumentation","CEC-related testing"],"image":"assets/images/uei-img-8868.jpg","imageAlt":"Residential fan airflow and CFM test duct","imageCaption":"Residential-fan airflow test duct in the Sacramento State lab.","imageFit":"cover","gallery":[{"src":"assets/images/uei-img-8868.jpg","alt":"Residential fan airflow and CFM test duct","title":"Airflow test duct","copy":"The long duct and controlled geometry support repeatable residential-fan measurements.","orientation":"landscape"},{"src":"assets/images/uei-img-8870.jpg","alt":"Wood test room and fan fixture under construction","title":"Controlled test room","copy":"The eight-foot test environment was built, sealed, and repaired to support standards-driven testing.","orientation":"landscape"},{"src":"assets/images/manufacturing-img-8774.jpg","alt":"Wood fixture construction detail from the UEI lab","title":"Fixture construction","copy":"Material, sealing, fastener, and access decisions affected the quality of the final test setup.","orientation":"portrait"}],"metrics":[{"value":"8 ft","label":"controlled test-room scale"},{"value":"HVI 916","label":"fan-test procedure exposure"},{"value":"CFM","label":"airflow and pressure measurement"},{"value":"Logged","label":"temperature and power data"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>Testing where setup quality directly affects the result.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Work</p><h3>Build and prepare controlled environments</h3><p>I helped construct the test room, seal fixtures, set up pressure and flow hardware, place sensors, and prepare data logging.</p></article><article><p class=\"project-eyebrow\">Responsibility</p><h3>Support repeatable measurements</h3><p>The work required following procedures, documenting changes, repairing leaks, and keeping the setup consistent between tests.</p></article></div>"},{"id":"gallery","label":"Photos","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>The airflow duct, test room, and fixture construction.</h2></div></div><div class=\"project-gallery gallery-count-3\"><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Airflow test duct — The long duct and controlled geometry support repeatable residential-fan measurements.\"><img loading=\"lazy\" src=\"assets/images/uei-img-8868.jpg\" alt=\"Residential fan airflow and CFM test duct\"></button><figcaption><strong>Airflow test duct</strong>The long duct and controlled geometry support repeatable residential-fan measurements.</figcaption></figure><figure class=\"landscape\"><button type=\"button\" data-lightbox data-caption=\"Controlled test room — The eight-foot test environment was built, sealed, and repaired to support standards-driven testing.\"><img loading=\"lazy\" src=\"assets/images/uei-img-8870.jpg\" alt=\"Wood test room and fan fixture under construction\"></button><figcaption><strong>Controlled test room</strong>The eight-foot test environment was built, sealed, and repaired to support standards-driven testing.</figcaption></figure><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Fixture construction — Material, sealing, fastener, and access decisions affected the quality of the final test setup.\"><img loading=\"lazy\" src=\"assets/images/manufacturing-img-8774.jpg\" alt=\"Wood fixture construction detail from the UEI lab\"></button><figcaption><strong>Fixture construction</strong>Material, sealing, fastener, and access decisions affected the quality of the final test setup.</figcaption></figure></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>Good data starts with a controlled setup.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Control leaks and geometry</h3><p>Sealing and fixture dimensions influence the measured airflow.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Keep instrumentation traceable</h3><p>Tubing, sensors, channels, and test conditions must be documented.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Repair without losing repeatability</h3><p>Changes to the room or fixture are recorded and checked before testing resumes.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The role added real test-engineering discipline.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Standards exposure</h3><p>Procedures and compliance goals shaped the work.</p></article><article><span>02</span><h3>Instrumentation practice</h3><p>Pressure, flow, temperature, and power data were handled together.</p></article><article><span>03</span><h3>Documentation habits</h3><p>Setup details and changes were treated as part of the result.</p></article></div>"}],"next":"Add anonymized test diagrams or sample data only when they can be shared appropriately.","fallbackPage":"projects/uei-lab/"},"abb-rexroth":{"id":"abb-rexroth","tone":"orange","eyebrow":"Industrial robotics coursework","title":"ABB and Rexroth robotics lab","lede":"Hands-on ME165 coursework using ABB robot hardware and Rexroth controls, with attention to controller state, I/O, emergency-stop behavior, and safe lab execution.","status":["ME165 coursework","ABB hardware","Rexroth controls"],"image":"assets/images/me165-image-111.jpg","imageAlt":"ABB robot and Rexroth controls in the ME165 laboratory","imageCaption":"ABB robot and controller hardware in the supervised ME165 lab.","imageFit":"contain","gallery":[{"src":"assets/images/me165-image-111.jpg","alt":"ABB robot and Rexroth controls in the ME165 laboratory","title":"Industrial robotics lab","copy":"The supervised setup included robot hardware, controller interfaces, cabling, and emergency-stop controls.","orientation":"portrait"}],"metrics":[{"value":"ABB","label":"industrial robot exposure"},{"value":"Rexroth","label":"controller-platform exposure"},{"value":"E-stop","label":"safety-state awareness"},{"value":"ME165","label":"hands-on coursework"}],"tabs":[{"id":"overview","label":"Overview","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Overview</p><h2>Controls concepts tied to real industrial hardware.</h2></div></div><div class=\"project-overview-grid\"><article><p class=\"project-eyebrow\">Coursework</p><h3>Work with the physical system</h3><p>The lab connected motion, controller interfaces, I/O, cabling, and safety states to the theory covered in class.</p></article><article><p class=\"project-eyebrow\">Scope</p><h3>Accurate hands-on exposure</h3><p>This is supervised academic experience, not production ownership. The portfolio keeps that distinction clear.</p></article></div>"},{"id":"gallery","label":"Photo","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Photos</p><h2>The supervised ABB and Rexroth lab setup.</h2></div></div><div class=\"project-gallery gallery-count-1\"><figure class=\"portrait\"><button type=\"button\" data-lightbox data-caption=\"Industrial robotics lab — The supervised setup included robot hardware, controller interfaces, cabling, and emergency-stop controls.\"><img loading=\"lazy\" src=\"assets/images/me165-image-111.jpg\" alt=\"ABB robot and Rexroth controls in the ME165 laboratory\"></button><figcaption><strong>Industrial robotics lab</strong>The supervised setup included robot hardware, controller interfaces, cabling, and emergency-stop controls.</figcaption></figure></div>"},{"id":"decisions","label":"Engineering","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>Safe state awareness came first.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Understand the stop path</h3><p>Emergency-stop and controller state were treated as part of every motion task.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Observe before changing</h3><p>Robot, controller, and I/O state were checked before commands were issued.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Document the real scope</h3><p>The work is described as coursework so the evidence remains credible.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The lab created a useful automation foundation.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Industrial context</h3><p>Controls concepts became connected to real equipment.</p></article><article><span>02</span><h3>Safety habits</h3><p>Motion and controller work were framed around safe execution.</p></article><article><span>03</span><h3>Career relevance</h3><p>The experience supports future commissioning and automation-support work.</p></article></div>"}],"next":"Build on the foundation with more direct robot programming, I/O integration, and documented fault recovery.","fallbackPage":"projects/abb-rexroth/"},"makerspace-manufacturing":{"id":"makerspace-manufacturing","tone":"orange","eyebrow":"Equipment and production support","title":"Makerspace + Vanquish Products","lede":"Two early roles that built practical habits around machine setup, training, inventory, finishing, inspection, packaging, and safe handoff. This project uses a role map because I do not have useful workplace photos.","status":["Makerspace support","Inventory management","Production finishing"],"image":"assets/graphics/experience-role-map.svg","imageAlt":"Illustrated responsibility map for Sierra College Makerspace and Vanquish Products roles","imageCaption":"Illustrated role map; no workplace photographs are used for these positions.","imageFit":"contain","gallery":[],"metrics":[{"value":"2 roles","label":"equipment and production support"},{"value":"CAD/CAM","label":"machine and file setup"},{"value":"Inventory","label":"staging and tracking"},{"value":"Finish","label":"deburr, inspect, pack, ship"}],"tabs":[{"id":"overview","label":"Roles","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Role overview</p><h2>Two jobs that built practical production habits.</h2></div></div>\n<div class=\"project-role-grid\">\n  <article><p class=\"project-eyebrow\">Sierra College Makerspace</p><h3>Makerspace Technical Assistant</h3><ul><li>Trained users on 3D printers, CNC routers, laser systems, woodworking, vinyl, and embroidery equipment.</li><li>Supported CAD/CAM, print setup, troubleshooting, maintenance, and shop safety.</li><li>Helped users move from an idea to a safe, workable process.</li></ul></article>\n  <article><p class=\"project-eyebrow\">Vanquish Products / ASB Products</p><h3>Inventory Manager &amp; Factory Support</h3><ul><li>Managed inventory and staged machined RC-car parts through production.</li><li>Deburred, polished, cleaned, inspected, and prepared aluminum parts for anodizing or laser etching.</li><li>Supported packaging, shipping, and vendor processing.</li></ul></article>\n</div>\n<p class=\"project-no-photo-note\"><strong>Photo note:</strong> I do not have useful workplace photos from these roles. The visual above is an illustrated responsibility map, not a photograph.</p>"},{"id":"workflow","label":"Workflows","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Workflow</p><h2>The work was built around safe, repeatable handoff.</h2></div></div><div class=\"project-flow compact-flow\"><article><span>01</span><h3>Makerspace setup</h3><p>Check the file, material, machine, tooling, and safety plan.</p></article><article><span>02</span><h3>User support</h3><p>Explain the process, supervise the first run, and leave the user more independent.</p></article><article><span>03</span><h3>Production flow</h3><p>Receive, stage, finish, inspect, and prepare parts for the next operation.</p></article><article><span>04</span><h3>Final handoff</h3><p>Package and ship parts with inventory and quality checks complete.</p></article></div>"},{"id":"decisions","label":"Lessons","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Engineering choices</p><h2>The small steps around a machine determine whether the work succeeds.</h2></div></div><div class=\"project-decision-grid compact-decisions\"><article class=\"project-decision\"><span>01</span><div><h3>Teach the process, not only the button</h3><p>Good support helps the next job go better without constant supervision.</p></div></article><article class=\"project-decision\"><span>02</span><div><h3>Treat finishing as production work</h3><p>Deburr, cleaning, inspection, and packaging affect quality and customer experience.</p></div></article><article class=\"project-decision\"><span>03</span><div><h3>Protect equipment and people</h3><p>Safe setup and maintenance are part of uptime, not separate from it.</p></div></article></div>"},{"id":"outcomes","label":"Results","html":"<div class=\"project-section-heading compact\"><div><p class=\"project-eyebrow\">Results</p><h2>The roles connected design intent to real production work.</h2></div></div><div class=\"project-outcome-grid compact-outcomes\"><article><span>01</span><h3>Broader machine fluency</h3><p>I supported several tools and workflows rather than one narrow process.</p></article><article><span>02</span><h3>Operator-support habits</h3><p>Training, safety, and clear handoff became part of the technical solution.</p></article><article><span>03</span><h3>Production perspective</h3><p>Inventory, finishing, inspection, and shipping showed what happens after machining.</p></article></div>"}],"next":"Keep this section evidence-based and add work samples only when they are mine and can be shown accurately.","fallbackPage":"projects/makerspace-manufacturing/"}}};
